import {useEffect} from 'react';
import type {ProjectData} from '../domain/types';
import {preparePublicExecution} from '../domain/exportPreparation';
import {jsonBytes,sha256} from '../storage/json';
import {worldSnapshotContents} from '../storage/archive';
import {useAuthorScope,useScenarioStore} from './StoreContext';
import {useSyncClient} from './SyncContext';
import {authorField,useAuthorField,useAuthorInput,flushAuthorDraft,AuthorDraftNotice} from './authorOperation';
import {PagedSelect} from './PagedSelect';
import {ListPager,useListWindow} from './ListWindow';
interface SharePlan {baseRevision:string;serverRevision:string;sourceVersionId:string;profileId:string;projectionHash:string;expiresAt:string|null;title:string;included:number;sourceHash:string}
interface SharedRecord {id:string;sourceVersionId:string;contentHash:string;withdrawnAt:string|null;expiresAt:string|null}
interface Member {accountId:string;role:string;expiresAt:string|null;revokedAt:string|null}
export function LimitedSharePanel({project}:{project:ProjectData}){
 const store=useScenarioStore(),client=useSyncClient(),scope=useAuthorScope(`limited-share:${project.projectId}`),[busy,setBusy]=useAuthorField(scope,'busy',false),[error,setError]=useAuthorField(scope,'error',''),[notice,setNotice]=useAuthorField(scope,'notice',''),[plan,setPlan]=useAuthorField<SharePlan|null>(scope,'plan',null),[version,setVersion]=useAuthorInput(scope,'version','',project.projectId,project.revision),[profile,setProfile]=useAuthorInput(scope,'profile','',project.projectId,project.revision),[expiry,setExpiry]=useAuthorInput(scope,'expiry','',project.projectId,project.revision),[account,setAccount]=useAuthorInput(scope,'account','',project.projectId,project.revision),[role,setRole]=useAuthorInput(scope,'role','reader',project.projectId,project.revision),[memberExpiry,setMemberExpiry]=useAuthorInput(scope,'memberExpiry','',project.projectId,project.revision),[snapshotIds,setSnapshotIds]=useAuthorInput<string[]>(scope,'snapshots',[],project.projectId,project.revision),[shares,setShares]=useAuthorField<SharedRecord[]>(scope,'shares',[]),[members,setMembers]=useAuthorField<Member[]>(scope,'members',[]),[membershipRevision,setMembershipRevision]=useAuthorField(scope,'membershipRevision',''),[grantPlan,setGrantPlan]=useAuthorField<Record<string,unknown>|null>(scope,'grantPlan',null),[memberPlan,setMemberPlan]=useAuthorField<Record<string,unknown>|null>(scope,'memberPlan',null),[grantFields,setGrantFields]=useAuthorInput<Record<string,string[]>>(scope,'fields',{},project.projectId,project.revision);
 const sharePage=useListWindow({items:shares,scope:`${scope}:shares`,size:30}),memberPage=useListWindow({items:members.map(m=>({...m,id:m.accountId})),scope:`${scope}:members`,size:30}),teamPage=useListWindow({items:project.entities.filter(e=>e.visibility==='team'&&!e.deletedAt),scope:`${scope}:team`,size:30});
 const pins=project.snapshots.map(s=>({id:s.id,label:`${s.versionLabel} · 作成 ${s.createdAt} · ${s.contentHash.slice(0,8)}`})),policies=project.entities.filter(e=>e.kind==='projection_profile'&&e.status==='confirmed'&&!e.deletedAt).map(e=>({id:e.id,label:e.name}));
 async function refresh(){if(!client||!store.accountId)return;const expected=client.getSession();setShares(await client.request<SharedRecord[]>('shares',{projectId:project.projectId},expected));const result=await client.request<{membershipRevision:string;members:Member[]}>('members',{projectId:project.projectId},expected);setMembers(result.members);setMembershipRevision(result.membershipRevision);}
 useEffect(()=>{if(!client||!store.accountId||!client.getSession().authenticated)return;void refresh().catch(cause=>setError((cause as Error).message));},[scope]);
 async function run(task:()=>Promise<void>){if(authorField<boolean>(scope,'busy'))return;setBusy(true);setError('');try{if(!client||!store.accountId)throw Error('DEDICATED_CONNECTION_REQUIRED');await flushAuthorDraft(scope);await task();}catch(cause){setError((cause as Error).message);}finally{setBusy(false);}}
 async function preview(){const source=structuredClone(project),selected=version,policy=profile,expiresAt=expiry?new Date(expiry).toISOString():null,state=await store.getSaveState(source.projectId),base=await store.getConfirmedSyncBase(source.projectId);if(!base||state.pendingCount||state.pendingAssetCount||state.syncState==='conflict')throw Error('共有前に保存待ち・素材bytes・競合を同期してください。');const worlds=await store.listWorldSnapshots(),result=await preparePublicExecution(source,{profile:'reader',projectionProfileId:policy,targetVersionId:selected,worldSnapshots:worldSnapshotContents(worlds),worldPins:Object.values(worlds).flatMap(w=>w.snapshots)}),pin=source.snapshots.find(s=>s.id===selected)!;setPlan({baseRevision:source.revision,serverRevision:base.serverRevision,sourceVersionId:selected,profileId:policy,projectionHash:await sha256(jsonBytes(result.projection)),expiresAt,title:result.projection.title,included:result.projection.entities.length,sourceHash:pin.contentHash});}
 const stale=!!plan&&plan.baseRevision!==project.revision;
 return <section className="settings-card" aria-label="限定共有の確認"><h2>限定共有</h2><p>公開名・公開文・公開IDを確認した固定版だけを共有します。現在稿の変更は既存の共有本文へ自動適用しません。</p><fieldset disabled={busy}><PagedSelect label="共有する固定版" scope={`${scope}:versions`} items={pins} value={version} onChange={id=>{setVersion(id);setPlan(null);}}/><PagedSelect label="共有する承認範囲" scope={`${scope}:profiles`} items={policies} value={profile} onChange={id=>{setProfile(id);setPlan(null);}}/><label>共有の現実の期限（省略可）<input type="datetime-local" value={expiry} onChange={e=>{setExpiry(e.target.value);setPlan(null);}}/></label><button className="button secondary" disabled={!version||!profile||!store.accountId} onClick={()=>void run(preview)}>限定版の名前・範囲・hashを確認</button>{plan&&<div><p>{plan.title} · 公開対象 {plan.included}件 · 固定版 {plan.sourceVersionId} · 公開hash {plan.projectionHash} · 期限 {plan.expiresAt??'なし'}</p><button className="button primary" disabled={stale} onClick={()=>void run(async()=>{const approved=structuredClone(plan),state=await store.getSaveState(project.projectId);if(state.pendingCount||state.pendingAssetCount||project.revision!==approved.baseRevision)throw Error('確認後に保存状態が変わりました。入力を保持して再確認してください。');const result=await client!.request<{id:string;contentHash:string}>('publish',{projectId:project.projectId,...approved});if(result.contentHash!==approved.projectionHash)throw Error('PROJECTION_HASH_MISMATCH');setPlan(null);await refresh();setNotice('確認した共有固定版を登録しました。受取人への送信は、リンクを確認して手動で行ってください。');})}>確認した限定版を登録</button></div>}{stale&&<p role="alert">確認後に作品が更新されました。入力を保持して再確認してください。</p>}
 <h3>共有した固定版</h3>{sharePage.items.map(s=><div key={s.id}><p>{s.id} · 元固定版 {s.sourceVersionId} · {s.withdrawnAt?'撤回済み':'有効'} · 期限 {s.expiresAt??'なし'}</p><label>確認する受取リンク<input readOnly value={new URL(`${import.meta.env.BASE_URL}?shared=${s.id}`,location.origin).href}/></label><button className="button danger small" disabled={!!s.withdrawnAt} onClick={()=>void run(async()=>{await client!.request('withdraw',{projectId:project.projectId,snapshotId:s.id});await refresh();setNotice('共有を撤回しました。新しい取得・指摘・素材の取得を停止します。既に持ち出されたコピーの消去は保証できません。');})}>この限定版を撤回</button></div>)}<ListPager {...sharePage} label="共有版"/>
 <h3>受取人と権限</h3><label>登録済みAuthアカウントID<input value={account} onChange={e=>setAccount(e.target.value)}/></label><label>権限<select value={role} onChange={e=>setRole(e.target.value)}><option value="reader">閲覧</option><option value="reviewer">閲覧・指摘</option><option value="editor">許可項目の編集・指摘</option><option value="owner">管理・作品全体</option></select></label><label>権限の現実の期限（省略可）<input type="datetime-local" value={memberExpiry} onChange={e=>setMemberExpiry(e.target.value)}/></label><p>閲覧・指摘の対象は下で選んだ固定版だけです。編集は別途、現在のteam情報と項目を許可します。</p>{sharePage.items.filter(s=>!s.withdrawnAt).map(s=><label className="check-label" key={s.id}><input type="checkbox" checked={snapshotIds.includes(s.id)} onChange={e=>setSnapshotIds(e.target.checked?[...snapshotIds,s.id]:snapshotIds.filter(id=>id!==s.id))}/>{s.id}</label>)}<button className="button secondary" disabled={!account} onClick={()=>void run(async()=>{const submitted={projectId:project.projectId,accountId:account,role,expiresAt:memberExpiry?new Date(memberExpiry).toISOString():null,snapshotIds:structuredClone(snapshotIds),revoked:false,membershipRevision};setMemberPlan(submitted);})}>指定した権限と固定版を確認</button>{memberPlan&&<div><p>確認した対象 {String(memberPlan.accountId)} · 権限 {String(memberPlan.role)} · 期限 {String(memberPlan.expiresAt??'なし')} · 基底 {String(memberPlan.membershipRevision)}</p><button className="button primary" onClick={()=>void run(async()=>{const approved=structuredClone(memberPlan);await client!.request('membership',approved);setMemberPlan(null);await refresh();setNotice('確認した権限と固定版を登録しました。');})}>確認した権限を保存</button></div>}{memberPage.items.map(m=><p key={m.accountId}>{m.accountId} · {m.role} · 期限 {m.expiresAt??'なし'} · {m.revokedAt?'失効':'有効'}<button className="button danger small" disabled={!!m.revokedAt} onClick={()=>void run(async()=>{await client!.request('membership',{projectId:project.projectId,accountId:m.accountId,role:m.role,expiresAt:null,revoked:true,snapshotIds:[],membershipRevision});await refresh();setNotice('権限を失効しました。次の取得・編集・素材アクセスをサーバーで拒否します。');})}>権限を失効</button></p>)}<ListPager {...memberPage} label="受取人"/>
 {role==='editor'&&<><h3>編集を許可するteam項目</h3>{teamPage.items.map(e=><div key={e.id}><strong>{e.name}</strong>{['name','status',...Object.keys(e.data).filter(k=>e.data[k as keyof typeof e.data]!==undefined).map(k=>'data.'+k)].map(field=><label className="check-label" key={field}><input type="checkbox" checked={(grantFields[e.id]??[]).includes(field)} onChange={event=>setGrantFields({...grantFields,[e.id]:event.target.checked?[...(grantFields[e.id]??[]),field]:(grantFields[e.id]??[]).filter(f=>f!==field)})}/>{field}</label>)}</div>)}<ListPager {...teamPage} label="編集許可の情報"/><button className="button secondary" disabled={!account} onClick={()=>void run(async()=>{const base=await store.getConfirmedSyncBase(project.projectId);setGrantPlan({projectId:project.projectId,accountId:account,serverRevision:base?.serverRevision,membershipRevision,scopes:Object.entries(grantFields).filter(([,fields])=>fields.length).map(([id,fields])=>({id,fields}))});setNotice('許可する項目と権限の基底を固定しました。対象と範囲を確認してください。');})}>選択した編集項目を確認</button>{grantPlan&&<div><pre>{JSON.stringify(grantPlan,null,2)}</pre><button className="button primary" onClick={()=>void run(async()=>{await client!.request('editor_grants',structuredClone(grantPlan));setGrantPlan(null);await refresh();setNotice('確認した編集項目を許可しました。競合・期限・対象版をサーバーで検証しました。');})}>確認した編集許可を保存</button></div>}</>}
 </fieldset>{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}{busy&&<p role="status">限定共有の確認・保存中…</p>}<AuthorDraftNotice scope={scope} revision={project.revision}/></section>;
}
